let exact = ["sk_live_", "sk_test_", "AKIA", "AIza", "-----BEGIN", "Bearer "];
for k in exact {
  let hits = find_strings(k);
  for h in hits {
    if h.value.contains(k) {
      report("Secret: " + k, h.address, "HIGH", h.value);
    }
  }
}
let loose = ["api_key", "apikey", "secret"];
for k in loose {
  let hits = find_strings(k);
  for h in hits {
    if h.value.len() <= 96 {
      report("Possible Secret: " + k, h.address, "MEDIUM", h.value);
    }
  }
}
